6188	/** 待机页信息卡每拍刷新：40px 时钟 + 状态列三行。 */
6189	static void helm_standby_card_tick(const bicycle_runtime_t * rt)
6190	{
6191	    char buf[32];
6192	    time_t now = time(NULL);
6193	    struct tm tmv;
6194	    bool have = false;
6195	    int hour = 0;
6196	    int min = 0;
6197	    int mon = 0;
6198	    int day = 0;
6199	    int wday = 0;
6200	
6201	    /* 本地时间：系统时间是 UTC，时区偏移在 devctl 里（tz_hms 同源）。
6202	     * 这里要的不只是时分还要年月日/星期，所以自己做一次偏移 + gmtime_r。 */
6203	    if (now >= 1704067200 && gmtime_r(&(time_t){(time_t)((long)now
6204	            + (long)myvendor_devctl_tz_min_get() * 60)}, &tmv) != NULL) {
6205	        have = true;
6206	        hour = tmv.tm_hour;
6207	        min = tmv.tm_min;
6208	        mon = tmv.tm_mon + 1;
6209	        day = tmv.tm_mday;
6210	        wday = (tmv.tm_wday >= 0 && tmv.tm_wday < 7) ? tmv.tm_wday : 0;
6211	    }
6212	
6213	    /* **时间无效也必须显示**（用户 2026-09-26："时间即使不正常也得显示，和静止界面
6214	     * 一样"）：没对上星/没设置时给 00:00，和状态栏同样的兜底。
6215	     * ⚠ 配套：sb_hm 初值必须是 0xFFFF，不能是 0——0 的语义恰好就是 "00:00"，
6216	     * 于是"hm != sb_hm"永远为假、标签一次都不会被设、一直空白（上板实测）。 */
6217	    {
6218	        const uint16_t hm = (uint16_t)(hour * 60 + min);
6219	
6220	        if (hm != s_sh.sb_hm) {
6221	            static const char * wd[7] = { "周日", "周一", "周二", "周三",
6222	                                          "周四", "周五", "周六" };
6223	
6224	            s_sh.sb_hm = hm;
6225	            if (have) {
6226	                lv_snprintf(buf, sizeof(buf), "%d月%d日 %s", mon, day, wd[wday]);
6227	            } else {
6228	                lv_snprintf(buf, sizeof(buf), "--月--日");
6229	            }
6230	            helm_label_set(s_sh.sb_date, buf);
6231	            lv_snprintf(buf, sizeof(buf), "%02d:%02d", hour, min);
6232	            helm_label_set(s_sh.sb_time, buf);
6233	            /* 半反屏局部刷新会留灰影 / 闪一下（用户 2026-09-26："和静止界面一样，
6234	             * 闪烁，消失时能看到灰色"；旧静止页同样如此 ⇒ 属既有的面板特性，
6235	             * 不是这轮引入的）。缓解：时间一变就把**整个左列**（日期 + 时钟）一起
6236	             * 失效重画，让新数字落在一块干净重绘的区域上，而不是只补字形那一小块。 */
6237	            if (s_sh.sb_date != NULL) {
6238	                lv_obj_invalidate(lv_obj_get_parent(s_sh.sb_date));
6239	            }
6240	        }
6241	    }
6242	
6243	    if (rt != NULL) {
6244	        lv_snprintf(buf, sizeof(buf), "%u 颗卫星",
6245	                    (unsigned)rt->gnss_satellites);
6246	        helm_label_set(s_sh.sb_st[0], buf);
6247	        helm_label_set(s_sh.sb_st[1], rt->gnss_valid ? "已定位"
6248	                                                     : "未定位");
6249	        if (s_sh.last_km > 0.05f) {
6250	            /* **取整、不留小数**（用户 2026-09-26："去掉小数点吧"）。
6251	             * 宽度实测（mism4_12）：
6252	             *   "上次 25 km"  ≈ 61px ⇒ 状态列需 83 ≤ 固定宽 84 ✅
6253	             *   "上次 128 km" ≈ 71px ⇒ 需 93 ❌ 三位数带单位放不下
6254	             *   "上次 128"    ≈ 52px ⇒ 需 74 ✅
6255	             * ⇒ 里程 ≥100 km 时**省掉单位**：宁可少个单位，也不要把字裁掉。
6256	             *   （单位不能无条件省：「公里/英里可切」所以数字离开单位就读不出来。） */
6257	            const int kmi = (int)(s_sh.last_km + 0.5f);
6258	
6259	            if (kmi < 100) {
6260	                lv_snprintf(buf, sizeof(buf), "上次 %d km", kmi);
6261	            } else {
6262	                lv_snprintf(buf, sizeof(buf), "上次 %d", kmi);
6263	            }
6264	        } else {
6265	            lv_snprintf(buf, sizeof(buf), "上次 -- km");
6266	        }
6267	        helm_label_set(s_sh.sb_st[2], buf);
6268	    }

