1196	/**
1197	 * @brief 关闭当前页面并返回前一页面（推荐版本）
1198	 *
1199	 * 执行流程：
1200	 *   1. 当前页面: will_disappear_cb → 关闭动画 → dis_disappear_cb → close_cb → 删除
1201	 *   2. 前一页面: 显示 → will_appear_cb → 打开动画 → dis_appear_cb
1202	 *
1203	 * ✓ 使用动画完成回调确保回调顺序
1204	 * ✓ 所有回调都在适当的时机触发
1205	 * ✓ 资源释放安全
1206	 * ✓ 与 lv_pm_open_page_msg() 流程对称
1207	 */
1208	int lv_pm_close_page_msg(void* msg_data)
1209	{
1210	    _nav_preempt_if_busy();
1211	
1212	    if (g_pm_history_count <= 1) {
1213	        LV_LOG_ERROR("[PAGE_MANAGER] 无法返回（路由表大小 <= 1）");
1214	        return -1;
1215	    }
1216	
1217	    /* 获取当前页面 */
1218	    lv_pm_id current_id = g_pm_history[g_pm_history_count - 1];
1219	    lv_pm_page_t current_page = _get_page_by_id(current_id);
1220	
1221	    if (current_page == NULL) {
1222	        LV_LOG_ERROR("[PAGE_MANAGER] 当前页面无效: ID=%d", current_id);
1223	        return -1;
1224	    }
1225	
1226	    current_page->flag.is_back = 1;
1227	
1228	    LV_LOG_INFO("[PAGE_MANAGER] [CLOSE] 关闭页面: ID=%d, Name=%s",
1229	           current_page->id, current_page->name);
1230	
1231	    /* Step 1: will_disappear - 页面即将隐藏 */
1232	    if (current_page->will_disappear_cb) {
1233	        current_page->will_disappear_cb(current_page);
1234	    }
1235	
1236	    /* Current page: EXIT (dis_appear). */
1237	    lv_pm_anima_play(current_page, LV_PM_ANIMA_EXIT, NULL, _on_normal_close_animation_complete);
1238	
1239	    /* ==================== 处理前一页面 ==================== */
1240	
1241	    g_pm_history_count--;
1242	    lv_pm_id prev_id = g_pm_history[g_pm_history_count - 1];
1243	    lv_pm_page_t prev_page = _get_page_by_id(prev_id);
1244	
1245	    if (prev_page == NULL) {
1246	        LV_LOG_ERROR("[PAGE_MANAGER] 前一页面无效: ID=%d", prev_id);
1247	        return -1;
1248	    }
1249	
1250	    prev_page->flag.is_back = 1;
1251	
1252	    LV_LOG_INFO("[PAGE_MANAGER] [CLOSE] 显示前一页面: ID=%d, Name=%s",
1253	           prev_page->id, prev_page->name);
1254	
1255	    _set_input_group(prev_page->group);
1256	
1257	    _pm_msg_replace(prev_page, msg_data);
1258	
1259	    /* will_appear */
1260	    if (prev_page->will_appear_cb) {
1261	        prev_page->will_appear_cb(prev_page);
1262	    }
1263	
1264	    /* 恢复定时器 */
1265	    if (prev_page->page_timer != NULL) {
1266	        lv_timer_resume(prev_page->page_timer);
1267	    }
1268	
1269	    /* 显示页面 */
1270	    if (prev_page->page != NULL) {
1271	        lv_obj_clear_flag(prev_page->page, LV_OBJ_FLAG_HIDDEN);
1272	    }
1273	
1274	    /* Restored page: ENTER (appear, is_back=1) — inverse of its earlier EXIT. */
1275	    lv_pm_anima_play(prev_page, LV_PM_ANIMA_ENTER, NULL, _on_back_open_animation_complete);
1276	
1277	    LV_LOG_INFO("[PAGE_MANAGER] [CLOSE] 页面关闭成功，已返回: ID=%d, Name=%s",
1278	           prev_page->id, prev_page->name);
1279	
1280	    return 0;
1281	}
