/**
 * @brief lv_pm nav drain。
 */
void lv_pm_nav_drain(void)
{
    if (g_nav_anim_ref > 0u) {
        LV_LOG_WARN("[PAGE_MANAGER] 导航抢占：结束未完成转场 (ref=%u)",
                    (unsigned)g_nav_anim_ref);
    }

    lv_pm_anima_drain_all();
    g_nav_anim_ref = 0u;
}

static void _nav_preempt_if_busy(void)
{
    if (lv_pm_nav_busy()) {
        lv_pm_nav_drain();
    }
}

