/* ---------------- 主界面入场动效（2026-10-28 WP-V3） ---------------- */
/** @brief 每组的时长：opa 0→255 与 y +10→0 同一条动画一起走（ms）。 */
#define HELM_SB_IN_MS   170u
/** @brief 组间错开（ms）：时钟块 → 状态列 → 操作条，总时长 90+170=260ms。 */
#define HELM_SB_IN_GAP  45u
/** @brief 入场起始的下移量（px），落回 0 即"回到动画前的位置"。 */
#define HELM_SB_IN_DY   10

/**
 * @brief 入场 exec：一个 0→255 的进度同时驱动不透明度与下移量。
 *
 * @details 拆成 opa/ty 两条动画会让每帧多一次 set_style，且两组曲线可能不同步；
 *          这里以进度 v 为主：v=0 ⇒ opa 0（透明、下移 10px），v=255 ⇒ 全不透明、归位。
 *          挂起（熄屏/待机）时直接返回，动画时间照走，由 done 回调落到末态。
 */
static void helm_sb_in_exec(void * var, int32_t v)
{
    lv_obj_t * obj = (lv_obj_t *)var;
    int32_t dy;

    if (helm_anim_is_suspended()) {
        return;
    }

    if (v < 0) {
        v = 0;
    } else if (v > 255) {
        v = 255;
    }

    lv_obj_set_style_opa(obj, (lv_opa_t)v, 0);
    dy = ((255 - v) * HELM_SB_IN_DY + 127) / 255;
    lv_obj_set_style_translate_y(obj, (lv_coord_t)dy, 0);
}

/** @brief 入场收尾：显式落到末态（全不透明、原位），不依赖最后一帧是否被挂起。 */
static void helm_sb_in_done(lv_anim_t * a)
{
    lv_obj_t * obj = (a != NULL) ? (lv_obj_t *)a->var : NULL;

    if (obj == NULL) {
        return;
    }

    lv_obj_set_style_opa(obj, LV_OPA_COVER, 0);
    lv_obj_set_style_translate_y(obj, 0, 0);
}

/** @brief 起一组入场动画（先清旧动画，再各走一条带 delay 的 lv_anim）。 */
static void helm_sb_in_run(lv_obj_t * obj, uint32_t delay)
{
    lv_anim_t a;

    if (obj == NULL) {
        return;
    }

    /* 同对象同 exec 的旧动画先删（等同于 helm_anim_run 的约定）；delay 需自带，
